class Solution {
public:
    int numberOfUniqueGoodSubsequences(string binary) {
        const int MOD = 1e9 + 7;
        long long dp = 0, ends0 = 0, ends1 = 0;
        int hasZero = 0;
        for (char c : binary) {
            if (c == '1') {
                long long add = (dp + 1 - ends1 + MOD) % MOD;
                dp = (dp + add) % MOD;
                ends1 = (ends1 + add) % MOD;
            } else {
                long long add = (dp - ends0 + MOD) % MOD;
                dp = (dp + add) % MOD;
                ends0 = (ends0 + add) % MOD;
                hasZero = 1;
            }
        }
        return (int)((dp + hasZero) % MOD);
    }
};
